96: function setupLayoutMock(window) {
97:   function makeRect(left, top, width, height) {
98:     return {
99:       left: left,
100:       top: top,
101:       width: width,
102:       height: height,
103:       right: left + width,
104:       bottom: top + height,
105:       x: left,
106:       y: top
