151:     // Content Shelves
152:     if (this.classList.contains('content-shelf')) {
153:       var shelfIdx = Array.from(this.parentElement.children).indexOf(this);
154:       return makeRect(0, 560 + shelfIdx * 400, 1920, 380);
155:     }
