### 5.2 Test Runner Framework & Check Macro
```javascript
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m'
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failureList = [];

async function check(suiteId, testId, description, fn) {
  totalChecks++;
  const label = `[${suiteId}.${testId}] ${description}`;
  const start = Date.now();
  try {
    await fn();
    passedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
  } catch (err) {
    failedChecks++;
    failureList.push({ label, error: err.message, stack: err.stack });
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label}`);
    console.log(`    ${C.gray}Error: ${err.message}${C.reset}`);
  }
}
```

### 5.3 Test Harness Factory Function
```javascript
function createM4Harness(options = {}) {
  const initialRoute = options.initialRoute || 'home';
  const customRoutes = options.mockRoutes || {};

  const htmlPath = path.resolve(__dirname, 'index.html');
  const configPath = path.resolve(__dirname, 'js/config.js');
  const navPath = path.resolve(__dirname, 'js/navigation.js');
  const tmdbPath = path.resolve(__dirname, 'js/tmdb.js');
  const appPath = path.resolve(__dirname, 'js/app.js');

  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, {
    url: 'http://localhost/#' + initialRoute,
    runScripts: 'outside-only'
  });
  const { window } = dom;

  window.__TEST_M4__ = true;
  installScrollMocks(window);
  installLayoutMock(window);
  installMockFetch(window, customRoutes);

  // Evaluate scripts in order
  window.eval(fs.readFileSync(configPath, 'utf8'));
  window.eval(fs.readFileSync(navPath, 'utf8'));
  if (fs.existsSync(tmdbPath)) {
    window.eval(fs.readFileSync(tmdbPath, 'utf8'));
  }
  window.eval(fs.readFileSync(appPath, 'utf8'));

  if (window.CinejoyApp && typeof window.CinejoyApp.init === 'function') {
    window.CinejoyApp.init();
  }

  return {
    dom,
    window,
    app: window.CinejoyApp,
    nav: window.SpatialNav,
    tmdb: window.TmdbClient
  };
}
```

### 5.4 Remote Key Simulation Utilities
```javascript
function sendKey(window, key, keyCode) {
  const event = new window.KeyboardEvent('keydown', {
    key: key,
    keyCode: keyCode,
    which: keyCode,
    bubbles: true,
    cancelable: true
  });
  window.dispatchEvent(event);
  return event;
}

function stepKey(window, key, keyCode) {
  if (window.SpatialNav && typeof window.SpatialNav.resetThrottle === 'function') {
    window.SpatialNav.resetThrottle();
  }
  return sendKey(window, key, keyCode);
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}
```

